$embedded = Join-Path $work 'r56_embedded_payload.zip'
[System.IO.File]::WriteAllBytes($embedded,[System.Convert]::FromBase64String(($payload -replace '\s','')))
Expand-Archive -LiteralPath $embedded -DestinationPath $work -Force
$log = Join-Path $work 'R56_TERMINAL.log'
Write-Host 'R56_BEGIN=FROZEN_4_POLICY_PAPER_REPLAY_16_SCENARIOS_4_EXCLUSIONS_NO_2024_NO_LIVE'
$exitcode = 1
try {
    & $py (Join-Path $work 'r56_paper_lab_engine.py') --repo $repo --downloads $downloads --work $work --out $out --pin (Join-Path $work 'R54_P0R5_EVENT_CENSUS_REPORT_PIN.json') 2>&1 | Tee-Object -FilePath $log
    $exitcode = $LASTEXITCODE
} catch {
    $_ | Out-String | Set-Content -Path (Join-Path $out 'R56_WRAPPER_EXCEPTION.txt') -Encoding UTF8
    Write-Host ('R56_WRAPPER_EXCEPTION=' + $_.Exception.Message)
    $exitcode = 1
} finally {
    if (Test-Path -LiteralPath $log -PathType Leaf) { Copy-Item -LiteralPath $log -Destination (Join-Path $out 'R56_TERMINAL.log') -Force }
    $packet = Join-Path $downloads ('UPLOAD_THIS_AKAH_R56_PAPER_LAB_' + $stamp + '.zip')
    Compress-Archive -Path (Join-Path $out '*') -DestinationPath $packet -CompressionLevel Optimal -Force
    Write-Host ('R56_UPLOAD_THIS=' + $packet)
    Write-Host ('R56_EXIT_CODE=' + $exitcode)
}
exit $exitcode
